let concatMany = xs =>
  switch xs {
  | [] => list{}
  | [x] => x
  | _ =>
    let len = A.length(xs)
    let v = ref(A.getUnsafe(xs, len - 1))
    for i in len - 2 downto 0 {
      v.contents = concat(A.getUnsafe(xs, i), v.contents)
