module N = Belt_internalAVLtree
module A = Belt_Array

type t<'key, 'a, 'id> = N.t<'key, 'a>

type cmp<'key, 'id> = Belt_Id.cmp<'key, 'id>

let empty = None
let fromArray = N.fromArray
