type id<'k, 'id> = Belt_Id.comparable<'k, 'id>
type cmp<'key, 'id> = Belt_Id.cmp<'key, 'id>

type t<'value, 'id> = {
  cmp: cmp<'value, 'id>,
  mutable data: N.t<'value>,
}

let rec remove0 = (nt, x, ~cmp) => {
  let k = nt.N.value
  let c = cmp(x, k)
  if c == 0 {
    let {N.left: l, right: r} = nt
    switch (l, r) {
    | (None, _) => r
    | (_, None) => l
    | (Some(_), Some(nr)) =>
      nt.right = N.removeMinAuxWithRootMutate(nt, nr)
      Some(N.balMutate(nt))
    }
  } else if c < 0 {
    switch nt.left {
    | None => Some(nt)
    | Some(l) =>
      nt.left = remove0(~cmp, l, x)
      Some(N.balMutate(nt))
    }
  } else {
    switch nt.right {
    | None => Some(nt)
    | Some(r) =>
      nt.right = remove0(~cmp, r, x)
      Some(N.balMutate(nt))
    }
  }
}

let remove = (d, v) => {
  let oldRoot = d.data
  switch oldRoot {
  | None => ()
  | Some(oldRoot2) =>
    let newRoot = remove0(~cmp=Belt_Id.getCmpInternal(d.cmp), oldRoot2, v)
    if newRoot !== oldRoot {
      d.data = newRoot
    }
  }
}

let rec removeMany0 = (t, xs, i, len, ~cmp) =>
  if i < len {
    let ele = A.getUnsafe(xs, i)
    let u = remove0(t, ele, ~cmp)
    switch u {
    | None => None
    | Some(t) => removeMany0(t, xs, i + 1, len, ~cmp)
    }
  } else {
    Some(t)
  }

let removeMany = (d, xs) => {
  let oldRoot = d.data
  switch oldRoot {
  | None => ()
  | Some(nt) =>
    let len = A.length(xs)
    d.data = removeMany0(nt, xs, 0, len, ~cmp=Belt_Id.getCmpInternal(d.cmp))
  }
}

let rec removeCheck0 = (nt, x, removed, ~cmp) => {
  let k = nt.N.value
  let c = Belt_Id.getCmpInternal(cmp)(x, k)
  if c == 0 {
    let () = removed.contents = true
    let {N.left: l, right: r} = nt
    switch (l, r) {
    | (None, _) => r
    | (_, None) => l
    | (Some(_), Some(nr)) =>
      nt.right = N.removeMinAuxWithRootMutate(nt, nr)
      Some(N.balMutate(nt))
    }
  } else if c < 0 {
    switch nt.left {
    | None => Some(nt)
    | Some(l) =>
      nt.left = removeCheck0(~cmp, l, x, removed)
      Some(N.balMutate(nt))
    }
  } else {
    switch nt.right {
    | None => Some(nt)
    | Some(r) =>
      nt.right = removeCheck0(~cmp, r, x, removed)
      Some(N.balMutate(nt))
    }
  }
}

let removeCheck = (d, v) => {
  let oldRoot = d.data
  switch oldRoot {
  | None => false
  | Some(oldRoot2) =>
    let removed = ref(false)
    let newRoot = removeCheck0(~cmp=d.cmp, oldRoot2, v, removed)
    if newRoot !== oldRoot {
      d.data = newRoot
    }
    removed.contents
  }
}

