  | Some(nt) =>
    let k = nt.N.value
    let c = cmp(x, k)
    if c == 0 {
      t
    } else {
      let {N.left: l, right: r} = nt
      if c < 0 {
        let ll = addCheck0(~cmp, l, x, added)
        nt.left = ll
      } else {
        nt.right = addCheck0(~cmp, r, x, added)
      }
      Some(N.balMutate(nt))
