  type t = int
  let cmp = Pervasives.compare
})

let s0 = Belt.Set.fromArray([5, 2, 3], ~id=module(IntCmp))
let s1 = Belt.Set.fromArray([3, 2, 5], ~id=module(IntCmp))

Belt.Set.eq(s0, s1) == true
