  switch n {
  | None => throw(Not_found)
  | Some(t) =>
    let v = t.value
    if x == v {
      v
    } else {
      getOrThrow(
        if x < v {
          t.left
        } else {
          t.right
        },
        x,
      )
    }
  }

/* ************************************************************************** */
let rec addMutate = (t, x: value) =>
  switch t {
  | None => N.singleton(x)
  | Some(nt) =>
    let k = nt.N.value
    if x == k {
      t
    } else {
      let {N.left: l, right: r} = nt
      if x < k {
        nt.left = addMutate(l, x)
