@deprecated({
  reason: "Use `|||` operator or `BigInt.bitwiseOr` instead.",
  migrate: %insert.unlabelledArgument(0) ||| %insert.unlabelledArgument(1),
  migrateInPipeChain: BigInt.bitwiseOr(),
})
external lor: (bigint, bigint) => bigint = "%orbigint"

@deprecated({
