  switch arity {
  | 1 => apply1(Obj.magic(o), a0)
  | 2 => param => apply2(Obj.magic(o), a0, param)
  | 3 => Obj.magic((param, \"param$1") => apply3(Obj.magic(o), a0, param, \"param$1"))
  | 4 =>
    Obj.magic((param, \"param$1", \"param$2") =>
