let compare = (x: int, y: int): int =>
  if x < y {
    -1
  } else if x == y {
    0
  } else {
    1
  }

let min = (x: int, y: int): int =>
  if x < y {
    x
  } else {
    y
  }

let max = (x: int, y: int): int =>
  if x > y {
    x
  } else {
    y
